WITH Src AS (SELECT *, REPLACE(product_name, ' ', '_') AS product_name_slug FROM products WHERE SIZE(tags) >= 1), agg AS (SELECT category, MAX(launch_date) AS last_launch_date, SUM(CASE WHEN category = 'Grocery' THEN cost ELSE 0 END) AS grocery_cost FROM Src GROUP BY category) SELECT category, last_launch_date, grocery_cost FROM agg WHERE grocery_cost >= 80 ORDER BY last_launch_date, category LIMIT 5
